const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs');
const {instagramDirectInbox}=require('../supabase/functions/_shared/instagram-direct-inbox.ts');
const {instagramInboxHandler}=require('../supabase/functions/instagram-inbox/handler.ts');
function fixture(){
 const saved=[],calls=[],attempts=[];let active={username:'valu_est',accountId:'42',connected:true,apiVerified:true};
 const sb={auth:{getUser:async(token)=>token==='valid'?{data:{user:{id:'owner'}}}:{data:{user:null},error:{}}},from(table){return {table,select(){return this},eq(){return this},like(){return this},maybeSingle(){return this},order(){return this},limit(){return this}}},rpc(name,args){return {name,args}}};
 const query=async q=>{if(q.table==='sanji_members')return {user_id:'owner'};if(q.table==='sanji_connections')return [{owner:'owner',provider:'instagram:42',summary:active}];if(q.table==='sanji_instagram_inbound')return saved;if(q.table==='sanji_instagram_reply_attempts')return attempts;if(q.name==='sanji_instagram_capture'){if(saved.some(x=>x.message_id===q.args.p_mid))return false;saved.push({message_id:q.args.p_mid,body:q.args.p_body});return true}if(q.name==='sanji_instagram_reserve_reply'){if(attempts.length)return {reserved:false,status:attempts[0].status};attempts.push({status:'pending'});return {reserved:true,peerId:'43'}}if(q.name==='sanji_instagram_finish_reply'){attempts[0].status=q.args.p_status;return null}throw Error('unexpected query')};
 const remote=async(url,opts={})=>{calls.push({url,opts});const u=new URL(url);if(opts.method==='POST')return {message_id:'sent'};if(u.pathname.endsWith('/me/conversations'))return u.searchParams.has('after')?{data:[{id:'thread2'}]}:{data:[{id:'thread1'}],paging:{next:'https://untrusted.invalid/ignored',cursors:{after:'cursor+page='}}};if(u.pathname.endsWith('/thread1'))return {messages:{data:[{id:'m1'},{id:'m2'}],paging:{next:'https://ignored.invalid/'}}};if(u.pathname.endsWith('/thread2'))return {messages:{data:[{id:'m3'}]}};if(u.pathname.endsWith('/m1'))return {id:'m1',created_time:new Date().toISOString(),from:{id:'43'},to:{data:[{id:'42'}]},message:'hello'};if(u.pathname.endsWith('/m2'))return {id:'m2',created_time:new Date().toISOString(),from:{id:'42'},to:{data:[{id:'43'}]},message:'outgoing'};if(u.pathname.endsWith('/m3'))return {id:'m3',created_time:new Date().toISOString(),from:{id:'44'},to:{data:[{id:'42'}]},attachments:{data:[{id:'media'}]}};throw Error('unexpected URL')};
 const env=k=>({SUPABASE_URL:'https://example.supabase.co',APP_ORIGIN:'https://dothegy.github.io',INSTAGRAM_DIRECT_REPLY_ENABLED:'true'}[k]||'');
 const connection=async()=>({id:'42',username:'valu_est',access_token:'fixture-secret',expires:Date.now()+3600000});
 return {sb,query,remote,env,connection,saved,calls,attempts,setAccount:v=>active=v};
}
test('manual sync pages on verified Graph cursor, records only inbound and never follows next URL',async()=>{const f=fixture(),svc=instagramDirectInbox(f),one=await svc.sync('owner');assert.equal(one.inserted,1);assert.equal(one.nextCursor,'cursor+page=');assert.equal(one.partialMessages,true);const two=await svc.sync('owner',one.nextCursor);assert.equal(two.inserted,1);assert.equal(two.nextCursor,null);assert.equal(f.saved[1].body,'본문 없음 또는 조회 불가 · Instagram에서 확인 필요');assert.ok(f.calls.every(x=>new URL(x.url).hostname==='graph.instagram.com'));assert.ok(f.calls.every(x=>!x.url.includes('fixture-secret')));await assert.rejects(()=>svc.sync('owner','https://evil.test/'));assert.equal((await svc.sync('owner')).inserted,0)});
