test('standalone handler has owner auth and no webhook, job, legacy send, or unauthenticated token exchange',async()=>{const f=fixture(),handler=instagramInboxHandler({...f,key:async()=>{},digest:async x=>x,encrypt:async()=>'',resolveSession:async()=>{throw Error('not used')},capabilities:async()=>({}),audit:async()=>{}}),url='https://example.supabase.co/functions/v1/instagram-inbox';let r=await handler(new Request(url+'/creator-instagram/inbox'));assert.equal(r.status,401);r=await handler(new Request(url+'/creator-instagram/inbox',{headers:{Authorization:'Bearer invalid'}}));assert.equal(r.status,401);r=await handler(new Request(url+'/jobs/run',{method:'POST',headers:{Authorization:'Bearer valid'}}));assert.equal(r.status,404);r=await handler(new Request(url+'/creator-instagram/webhook',{method:'POST'}));assert.equal(r.status,401);r=await handler(new Request(url+'/oauth/instagram/callback',{method:'POST'}));assert.equal(r.status,405);r=await handler(new Request(url+'/oauth/instagram/callback?state=test-state&code=test-code'));assert.equal(r.status,302);const location=new URL(r.headers.get('location'));assert.equal(location.origin,'https://dothegy.github.io');assert.equal(location.search,'');assert.match(location.hash,/instagram-connect/);assert.equal(r.headers.get('referrer-policy'),'no-referrer');assert.equal(f.calls.length,0);r=await handler(new Request(url+'/creator-instagram/inbox',{headers:{Authorization:'Bearer valid',origin:'https://evil.invalid'}}));assert.equal(r.status,403)});
test('only dedicated Instagram paths switch service; unrelated app paths retain bright-function',()=>{const api=fs.readFileSync('web/supabase-api.js','utf8'),cfg=fs.readFileSync('web/supabase-config.js','utf8');assert.match(api,/path\.startsWith\("\/creator-instagram\/"\) \? instagramInboxFunctionUrl : path === "\/dot-snapshot" \|\| path\.startsWith\("\/dot-snapshot\/"\) \? dotSnapshotFunctionUrl : edgeFunctionUrl/);assert.match(cfg,/instagram-inbox/);const handler=fs.readFileSync('supabase/functions/instagram-inbox/handler.ts','utf8');assert.doesNotMatch(handler,/\/jobs\/run|\/drafts\/|creator-instagram\/webhook/)});
test('OAuth state belonging to another logged-in owner cannot be consumed or sent to Meta',async()=>{const f=fixture();let deletes=0,network=0;const sb={...f.sb,from(table){return {table,select(){return this},eq(){return this},like(){return this},maybeSingle(){return this},delete(){deletes++;return this}}}};const query=async q=>q.table==='sanji_members'?{user_id:'owner'}:q.table==='sanji_oauth_states'?{state:'state',owner:'another-owner',provider:'instagram_message_connect',expires:new Date(Date.now()+60000).toISOString()}:null;const handler=instagramInboxHandler({...f,sb,query,key:async()=>{},digest:async x=>x,encrypt:async()=>'',resolveSession:async()=>{},capabilities:async()=>({}),audit:async()=>{},remote:async()=>{network++;return {}}});const req=new Request('https://example.supabase.co/functions/v1/instagram-inbox/creator-instagram/oauth/complete',{method:'POST',headers:{Authorization:'Bearer valid','Content-Type':'application/json'},body:JSON.stringify({state:'state',code:'code'})});assert.equal((await handler(req)).status,400);assert.equal(deletes,0);assert.equal(network,0)});
