test('changing context or editing while sync is in flight never replaces user input',async()=>{const vm=require('node:vm'),src=fs.readFileSync('private/ui/app.js','utf8'),a=src.indexOf('async function syncInstagramInbox('),b=src.indexOf('function inboxThreadCategory(',a);let release,rendered=0;const user={id:'owner'},ctx={instagramSyncBusy:false,inboxEdited:false,me:user,inboxRequestGeneration:1,instagramInboxOwner:null,instagramInboxCursor:null,instagramInboxOffset:0,instagramInboxHasMore:false,location:{hash:'#inbox'},toast:x=>ctx.message=x,api:()=>new Promise(resolve=>release=resolve),inboxPage:async()=>{rendered++}};vm.createContext(ctx);vm.runInContext(src.slice(a,b)+';this.sync=syncInstagramInbox;',ctx);const first=ctx.sync(false);ctx.inboxEdited=true;release({inserted:1,nextCursor:null});await first;assert.equal(rendered,0);assert.match(ctx.message,/편집/);assert.equal(ctx.inboxEdited,true);ctx.inboxEdited=false;const second=ctx.sync(false);ctx.me={id:'other'};release({inserted:1,nextCursor:null});await second;assert.equal(rendered,0)});
