test('bounded sync resumes five details at a time, rejects changed prefixes and retries idempotently',async()=>{const f=fixture(),ids=Array.from({length:12},(_,i)=>'m'+i);let changed=false,calls=0;const remote=async(url,opts)=>{calls++;assert.ok(opts.signal);const u=new URL(url),id=decodeURIComponent(u.pathname.split('/').pop());if(id==='conversations')return {data:[{id:'thread'}]};if(id==='thread')return {messages:{data:(changed?['different',...ids.slice(1)]:ids).map(id=>({id}))}};return {id,created_time:new Date().toISOString(),from:{id:'43'},to:{data:[{id:'42'}]},message:'received'}};const svc=instagramDirectInbox({...f,remote});let before=calls,one=await svc.sync('owner');assert.equal(calls-before,7);assert.equal(one.inserted,5);assert.match(one.nextCursor,/^r1\./);before=calls;const two=await svc.sync('owner',one.nextCursor);assert.equal(calls-before,7);assert.equal(two.inserted,5);changed=true;await assert.rejects(()=>svc.sync('owner',two.nextCursor),e=>e.syncReason==='messages_changed');changed=false;before=calls;const three=await svc.sync('owner',two.nextCursor);assert.equal(calls-before,4);assert.equal(three.inserted,2);assert.equal(three.nextCursor,null);const replay=await svc.sync('owner',one.nextCursor);assert.equal(replay.inserted,0);assert.equal(f.saved.length,12)});
test('OAuth diagnostics report only fixed stages and numeric provider codes, never credentials',async()=>{const {creatorInstagramOauth}=require('../supabase/functions/instagram-inbox/oauth.ts');const values=['secret-token','secret-code','secret-state','https://private.example','provider private text'];let current;const sb={from(){const q={select(){return q},eq(){return q},maybeSingle(){return Promise.resolve({state:'hashed',owner:'owner',expires:'2099-01-01T00:00:00Z'})},delete(){return q},then(resolve){resolve([{state:'hashed'}])}};return q}};const service=(remote,resolveSession)=>creatorInstagramOauth({sb,query:x=>x,env:()=>values[0],key:async()=>{},digest:async()=> 'hashed',encrypt:async()=>'',remote,resolveSession,capabilities:async()=>({}),audit:async()=>{},oauthStateProblem:()=>null});const url=new URL('https://example.test/?state='+values[2]+'&code='+values[1]);const error=Object.assign(Error(values.join(' ')),{httpStatus:400,metaCode:123,metaSubcode:456});for(const [stage,svc] of [['short_exchange',service(async()=>{throw error},async()=>({}))],['long_exchange',service(async(u)=>{if(u.includes('access_token')&&u.includes('graph.'))throw error;return {access_token:'temporary'}},async(t,r)=>{try{await r('https://graph.instagram.com/access_token',{},'')}catch{}return {id:'1',username:'valu_est',tokenMode:'short'}})],['profile',service(async(u)=>{if(u.includes('/me'))throw error;return {access_token:'temporary'}},async(t,r)=>r('https://graph.instagram.com/me',{},''))]]){try{await svc.callback(url,'https://example.test','owner');assert.fail('must fail')}catch(e){assert.equal(e.oauthStage,stage);assert.equal(e.metaCode,123);assert.equal(e.metaSubcode,456);const serialized=JSON.stringify({stage:e.oauthStage,http:e.httpStatus,code:e.metaCode,subcode:e.metaSubcode,message:e.message});for(const value of values)assert.equal(serialized.includes(value),false)}}const wrong=service(async()=>({access_token:'temporary'}),async()=>({id:'1',username:'wrong',tokenMode:'long'}));await assert.rejects(()=>wrong.callback(url,'https://example.test','owner'),e=>e.oauthStage==='account');});
