test('sync reports bounded progress and stops only an identical provider cursor without exposing it',async()=>{const f=fixture(),logs=[],original=console.info;console.info=x=>logs.push(x);try{let next='opaque-test-cursor';const remote=async(url,opts)=>{const u=new URL(url);if(u.pathname.endsWith('/me/conversations'))return {data:[{id:'thread1'}],paging:{next:'https://ignored.invalid',cursors:{after:next}}};return f.remote(url,opts)};const svc=instagramDirectInbox({...f,remote});let r=await svc.sync('owner','opaque-test-cursor');assert.equal(r.progress.cursorStalled,true);assert.equal(r.progress.hasMore,false);assert.equal(r.nextCursor,null);assert.equal(r.progress.inputCursorKind,'provider');assert.equal(r.progress.inputResumeOffset,0);assert.equal(r.progress.detailsChecked,2);assert.equal(r.progress.detailsSkipped,1);assert.equal(r.progress.inserted,1);assert.doesNotMatch(logs.join(' '),/opaque-test-cursor|ignored.invalid|fixture-secret/);next='another-cursor';r=await svc.sync('owner','opaque-test-cursor');assert.equal(r.inserted,0);assert.equal(r.progress.cursorStalled,false);assert.equal(r.progress.hasMore,true);assert.equal(r.nextCursor,'another-cursor')}finally{console.info=original}});
test('manual peer lookup needs existing inbound evidence and makes at most one provider request',async()=>{const f=fixture(),events=[];let found=false;const query=async q=>{if(q.table==='sanji_instagram_inbound')return found?[{message_id:'known'}]:[];if(q.name==='sanji_instagram_observe_peer'){events.push(q.args);return true}return f.query(q)},remote=async(url,options)=>{const u=new URL(url);assert.equal(u.hostname,'graph.instagram.com');assert.equal(u.pathname,'/v24.0/43');assert.equal(u.searchParams.get('fields'),'name,username');assert.ok(options.signal);assert.equal(options.method,'GET');return {username:'real.creator',name:'상대 이름'}},svc=instagramDirectInbox({...f,query,remote});await assert.rejects(()=>svc.lookupPeer('owner','43'));assert.equal(events.length,0);await assert.rejects(()=>svc.lookupPeer('owner','https://evil.test/'));found=true;assert.deepEqual(await svc.lookupPeer('owner','43'),{found:true});assert.equal(events.length,1);assert.equal(events[0].p_owner,'owner');assert.equal(events[0].p_account,'42');assert.equal(events[0].p_peer,'43');assert.equal(events[0].p_mid,'known');assert.equal(events[0].p_username,'real.creator');assert.equal(events[0].p_name,'상대 이름');await assert.rejects(()=>instagramDirectInbox({...f,query,remote:async()=>({id:'44',username:'other'})}).lookupPeer('owner','43'));await assert.rejects(()=>instagramDirectInbox({...f,query,remote:async()=>({id:43,username:'other'})}).lookupPeer('owner','43'));assert.deepEqual(await instagramDirectInbox({...f,query,remote:async()=>({username:'valu_est',name:'내 계정'})}).lookupPeer('owner','43'),{found:false});assert.equal(events.length,1)});
test('inbound sender metadata is recorded only after identity-verified capture; unsafe username is never cached',async()=>{const f=fixture(),events=[],query=async q=>{if(q.name==='sanji_instagram_observe_peer'){events.push(q.args);return true}return f.query(q)},remote=async(url,options)=>{const r=await f.remote(url,options);if(r.id==='m1')r.from.username='creator.real';if(r.id==='m2')r.from.username='outgoing';if(r.id==='m3')r.from.username='bad/name';return r},svc=instagramDirectInbox({...f,query,remote});await svc.sync('owner');assert.equal(events.length,1);assert.equal(events[0].p_peer,'43');assert.equal(events[0].p_mid,'m1');assert.equal(events[0].p_username,'creator.real');await svc.sync('owner','cursor+page=');assert.equal(events.length,1)});
test('peer profiles are projected only for current owner account and exact peer',async()=>{const filters=[],rows=[{message_id:'m1',peer_id:'43',received_at:'2026-11-02T00:00:00Z',body:'hello'},{message_id:'m2',peer_id:'44',received_at:'2026-11-02T00:00:00Z',body:'hi'}],sb={from(table){return {table,select(){return this},eq(k,v){filters.push([table,k,v]);return this},like(){return this},order(){return this},range(){return this},in(k,v){this.ids=v;return this}}},rpc(name,args){return {name,args}}},query=async q=>q.name==='sanji_tagby_evidence_for_peers'?[{peer_id:'43',handle:'verified.name'}]:q.table==='sanji_connections'?[{provider:'instagram:42',summary:{username:'valu_est',accountId:'42',connected:true,apiVerified:true}}]:q.table==='sanji_instagram_inbound'?rows:q.table==='sanji_instagram_peer_profiles'?[{peer_id:'43',username:'verified.name',display_name:'이름'}]:[],svc=instagramDirectInbox({sb,query,connection:async()=>({id:'42',username:'valu_est',access_token:'fixture',expires:Date.now()+60000}),remote:async()=>{},env:()=>''});const result=await svc.list('owner');assert.equal(result.items[0].peerProfile.username,'verified.name');assert.deepEqual(result.items[0].tagbyEvidence,{source:'tagby',recommended:true,sent:true,verified:true,handle:'verified.name',provenance:'operator_attested'});assert.equal(result.items[1].tagbyEvidence,null);assert.equal(result.items[1].peerProfile,null);assert.ok(filters.some(x=>x[0]==='sanji_instagram_peer_profiles'&&x[1]==='owner'&&x[2]==='owner'));assert.ok(filters.some(x=>x[0]==='sanji_instagram_peer_profiles'&&x[1]==='account_id'&&x[2]==='42'))});
test('peer lookup HTTP endpoint requires authentication and sends one bounded profile request only for inbound peer',async()=>{const f=fixture(),events=[],calls=[],query=async q=>{if(q.table==='sanji_instagram_inbound')return [{message_id:'known'}];if(q.name==='sanji_instagram_observe_peer'){events.push(q.args);return true}return f.query(q)},remote=async(url,options)=>{calls.push({url,options});return {username:'verified.name',name:'확인된 이름'}},handler=instagramInboxHandler({...f,query,remote,key:async()=>{},digest:async x=>x,encrypt:async()=>'',resolveSession:async()=>({}),capabilities:async()=>({}),audit:async()=>{}}),request=(token,peer)=>new Request('https://example.supabase.co/functions/v1/instagram-inbox/creator-instagram/peer-lookup',{method:'POST',headers:{...(token?{Authorization:'Bearer '+token}:{}),'Content-Type':'application/json'},body:JSON.stringify({peerId:peer})});assert.equal((await handler(request(null,'43'))).status,401);assert.equal(calls.length,0);assert.equal((await handler(request('valid','bad/path'))).status,400);assert.equal(calls.length,0);const response=await handler(request('valid','43'));assert.equal(response.status,200);assert.deepEqual(await response.json(),{found:true});assert.equal(calls.length,1);assert.equal(events.length,1);assert.equal(events[0].p_owner,'owner');assert.equal(events[0].p_account,'42');assert.equal(events[0].p_peer,'43')});

test('numeric provider peer IDs are not rounded into a different identity',async()=>{const f=fixture(),events=[],query=async q=>{if(q.name==='sanji_instagram_observe_peer'){events.push(q.args);return true}return f.query(q)},remote=async(url,options)=>{const r=await f.remote(url,options);if(r.id==='m1'){r.from.id=9007199254740993;r.from.username='verified.name'}return r},svc=instagramDirectInbox({...f,query,remote});const result=await svc.sync('owner');assert.equal(result.inserted,0);assert.equal(events.length,0);assert.equal(f.saved.length,0)});
test('creator-context route requires login and never queries Meta or sends',async()=>{const f=fixture(),calls=[],query=async q=>{if(q.table==='sanji_instagram_inbound')return [{message_id:'known'}];if(q.table==='sanji_instagram_peer_profiles')return {username:'creator',username_observed_at:new Date().toISOString()};if(q.table==='sanji_creator_recovery')return [{id:'c',handle:'creator',bio:'공개 소개',category:'여행',profile_url:'https://instagram.com/creator',link_status:'source_confirmed'}];if(q.table==='sanji_creator_one_click_templates'||q.table==='sanji_instagram_public_research')return [];return f.query(q)},handler=instagramInboxHandler({...f,query,remote:async(...args)=>{calls.push(args);throw Error('not allowed')},key:async()=>{},digest:async x=>x,encrypt:async()=>'',resolveSession:async()=>({}),capabilities:async()=>({}),audit:async()=>{}}),request=token=>new Request('https://example.supabase.co/functions/v1/instagram-inbox/creator-instagram/creator-context',{method:'POST',headers:{...(token?{Authorization:'Bearer '+token}:{}),'Content-Type':'application/json'},body:JSON.stringify({peerId:'43'})});assert.equal((await handler(request(null))).status,401);const response=await handler(request('valid'));assert.equal(response.status,200);assert.equal((await response.json()).matched,true);assert.equal(calls.length,0)});
test('evidence write endpoints require login, bind owner and account on server, and make no provider calls',async()=>{const f=fixture(),events=[],remoteCalls=[],query=async q=>{if(q.name==='sanji_tagby_evidence_import'||q.name==='sanji_instagram_research_import'){events.push(q);return 1}return f.query(q)},handler=instagramInboxHandler({...f,query,remote:async(...x)=>{remoteCalls.push(x);throw Error('unexpected')},key:async()=>{},digest:async x=>x,encrypt:async()=>'',resolveSession:async()=>({}),capabilities:async()=>({}),audit:async()=>{}}),request=(route,token,body)=>new Request('https://example.supabase.co/functions/v1/instagram-inbox/creator-instagram/'+route,{method:'POST',headers:{...(token?{Authorization:'Bearer '+token}:{}),'Content-Type':'application/json'},body:JSON.stringify(body)});assert.equal((await handler(request('tagby-evidence',null,{attested:true,rows:[{}]}))).status,401);assert.equal((await handler(request('tagby-evidence','valid',{attested:true,rows:[{}],owner:'other'}))).status,400);assert.equal((await handler(request('tagby-evidence','valid',{attested:true,rows:[{}]}))).status,200);assert.equal(events[0].args.p_owner,'owner');assert.equal(events[0].args.p_account,'42');assert.equal((await handler(request('public-research','valid',{attested:true,peerId:'43',profileUrl:'https://www.instagram.com/test/',observedAt:new Date().toISOString(),topics:['travel'],sources:['https://www.instagram.com/test/p/Post/'],summary:'공개 관찰'}))).status,200);assert.equal(events[1].args.p_owner,'owner');assert.equal(events[1].args.p_account,'42');assert.equal((await handler(request('public-research','valid',{attested:true,peerId:'43',profileUrl:'https://www.instagram.com/test/',observedAt:'2026-11-03T03:17:00',topics:['travel'],sources:['https://www.instagram.com/test/p/Post/'],summary:'공개 관찰'}))).status,400);assert.equal(events.length,2);assert.equal(remoteCalls.length,0)});
